 h.restart(); const facts=()=>h.hub.sessionView(sid)!.queue.find(e=>e.track.id===id)!.facts!;
 expect(facts().inStation).toBe(true);
 h.clock.t+=DAY_MS;(h.hub as any).prune();expect(h.sql.first('SELECT COUNT(*) AS n FROM plays WHERE track_id=?',id)!.n).toBe(0);
 expect(facts().inStation).toBe(true);h.restart();
 console.log('after wake',facts(),songTags(null,facts(),0,true));
