import {expect,it} from '/workspace/ts-review-bcc192/node_modules/vitest/dist/index.js';
import {onboarded} from '/workspace/ts-review-bcc192/test/hub/harness.ts';
import {DAY_MS} from '/workspace/ts-review-bcc192/src/core/types.ts';
import {songTags} from '/workspace/ts-review-bcc192/src/client/components/song-tags-text.ts';
it('pruned 181-day play is newer than six calendar months',async()=>{
 const h=await onboarded({tracks:200});const sid=h.stationIds[0]!;await h.hub.play(sid);
 h.clock.t=Date.parse('2026-10-08T16:00:00Z');
 const id=h.hub.sessionView(sid)!.queue[4]!.track.id;const at=h.clock.t-181*DAY_MS;
 h.sql.run('INSERT INTO plays (played_at,track_id,context_uri,station_id,ignored,meta) VALUES (?,?,NULL,?,0,NULL)',at,id,sid);
 h.sql.run('INSERT INTO memory (id,last_played_at,plays,early_skips,last_skipped_at,thumb) VALUES (?,?,1,0,NULL,0)',id,at);
 h.clock.t+=DAY_MS;(h.hub as any).prune();h.restart();
 const facts=h.hub.sessionView(sid)!.queue.find(e=>e.track.id===id)!.facts!;
 const sixMonths=new Date(h.clock.t);sixMonths.setUTCMonth(sixMonths.getUTCMonth()-6);
 console.log(JSON.stringify({now:new Date(h.clock.t),heard:new Date(at),sixMonths,sinceDays:(h.clock.t-at)/DAY_MS,facts,tags:songTags(null,facts,0,true)}));
 expect(facts.inStation).toBe(false);expect(at).toBeGreaterThan(sixMonths.getTime());
});
